 heads.append({'language':lang,'normalized_head':head,'sense':'structured_assembly_or_scheme','identity_fact_status':'independently_supported_lexical_row','finite_source_record':r,'source':str(p),'source_container_id':id,'dictionary_source':dictionary,'membership_status':'pending_new_family_promotion','identity_binding_authorized':False})
