out={'preparation_script':'scripts/prepare-associative-v6-system-promotion-research.py','script_sha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest(),'schema_version':6,'stage':'system-international-promotion-research-20261003','source_head':'7a40c30e9d95f8c64d9e0cd40d2d560bbc6808e0','production_enabled':False,'binding_authorized':False,'accepted_membership_authorized':False,'status':'promotion_research_requires_catalog_and_finite_corpus_frame','candidate_packets':packets,'source_evidence_clusters':metadata,'independent_head_facts':heads,'canonical_boundary_review':{'proposed_base':'system','canonical_decision':None,'status':'explicit_linguistic_recommendation_not_catalog_approval','rationale':'The whole modern English/German lexical base system recurs in independently attested French, Spanish, Italian and Russian loans from Greek systēma through Latin or French mediation. This is a recommendation based on the whole international lexical row, not shortest substring selection. systema keeps the longer full source noun form rather than the compact modern international head; this recommendation is not a general Greek/Latin ending-removal rule. syst and sys cut recognizability. Greek/Latin systemat- in derivations must be modeled as a branch stem, not a reason to invent substring membership. Preserve both ped under-stripping and creat over-stripping controls.','under_stripping_candidate':'systema','over_stripping_candidates':['syst','sys'],'derivational_stem_requires_separate_review':'systemat'},'national_form_review':[{'language':l,'lexical_form':w,'status':'proved_noun_head_form_not_general_reflex'} for l,w,h,s in plan],'negative_alias_control':{'alias':'sostav','word':'состав','source_record':counter[0],'source':str(p),'finding':'The Russian lexical translation состав is not the borrowed system element. The entire 24-record Russian pool in the Greek container must not be promoted on semantic similarity. The actual система record is independently frozen from surface:ru:sistem.','source_pool_records':24,'automatic_membership_removal':False},'new_catalog_promotions':0,'new_memberships':0,'current_queue_records_resolved':0,'input_sha256':proofs,'limitations':['Independent dictionaries establish the international lexical row, not every compound or all legacy member arrays.','No source etymological or surface container is imported wholesale.','Corpus part-of-speech and sense ambiguity, including sistema verb forms, must be scoped before noun identity binding.','General national reflexes and additional morphology require separate evidence.','Promotion must extend the existing catalog and exact finite frame; the six current seed queues cannot stand in for that frame.','This explicitly unauthorized research recipe cannot be passed into the existing stage integrator.']}
